#!/usr/bin/env python3
import csv, gzip, io, json, os, sys
from datetime import datetime, timedelta, timezone, date
from decimal import Decimal, ROUND_HALF_UP
from zoneinfo import ZoneInfo

UTC = timezone.utc


def read_text(path):
    with open(path, 'rb') as f:
        data = f.read()
    if data[:2] == b'\x1f\x8b':
        data = gzip.decompress(data)
    return data.decode('utf-8-sig')


def lines_of(text):
    return [l for l in text.replace('\r\n', '\n').replace('\r', '\n').split('\n') if l.strip() != '']


def epoch_of(dt):
    return int(dt.astimezone(UTC).timestamp()) if dt.tzinfo else None


def local_to_epoch(naive, tz, dst=None):
    """dst: None -> first occurrence; True/False -> choose DST/standard for ambiguous."""
    a = naive.replace(tzinfo=tz, fold=0)
    b = naive.replace(tzinfo=tz, fold=1)
    if a.utcoffset() != b.utcoffset():
        if dst is None or dst:
            pick = a if a.dst() else b
            if dst is None:
                pick = a
        else:
            pick = a if not a.dst() else b
            # choose the one without dst
        if dst is not None:
            cands = [x for x in (a, b) if bool(x.dst()) == dst]
            pick = cands[0] if cands else a
        return int(pick.timestamp())
    return int(a.timestamp())


def std_offset(tz, when_epoch):
    d = datetime.fromtimestamp(when_epoch, UTC)
    for dd in (d, datetime(d.year, 1, 1, tzinfo=UTC), datetime(d.year, 7, 1, tzinfo=UTC)):
        l = dd.astimezone(tz)
        if not l.dst():
            return l.utcoffset()
    return d.astimezone(tz).utcoffset() - d.astimezone(tz).dst()


def dir_norm(s):
    s = s.strip().upper()
    if s in ('IN', 'CLOCK_IN', 'K', 'I'):
        return 'IN'
    if s in ('OUT', 'CLOCK_OUT', 'G', 'O'):
        return 'OUT'
    raise ValueError(s)


def parse_abbr(text, tz):
    out = []
    header = None
    for row in csv.reader(lines_of(text)):
        row = [c.strip() for c in row]
        if 'Badge' in row and 'Punch' in row:
            header = {n: i for i, n in enumerate(row)}
            continue
        if header is None:
            continue
        g = lambda n: row[header[n]]
        m, d, y = g('Date').split('/')
        t = g('Time').upper()
        ap = None
        if t.endswith('AM') or t.endswith('PM'):
            ap = t[-2:]
            t = t[:-2].strip()
        hh, mm, ss = [int(x) for x in t.split(':')]
        if ap:
            hh = hh % 12 + (12 if ap == 'PM' else 0)
        naive = datetime(int(y), int(m), int(d), hh, mm, ss)
        z = g('Zone').upper()
        dst = True if z.endswith('DT') else (False if z.endswith('ST') else None)
        out.append((g('Record'), g('Badge'), dir_norm(g('Punch')), local_to_epoch(naive, tz, dst)))
    return out


def parse_epoch(text, tz):
    out = []
    schema = 1
    for l in lines_of(text):
        o = json.loads(l)
        if not isinstance(o, dict):
            continue
        if 'schema' in o and len(o) == 1:
            schema = int(o['schema'])
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            out.append((str(o['punch_id']), o['employee'], dir_norm(o['direction']), int(o['epoch_ms']) // 1000))
        else:
            if 'ts_ms' in o:
                ts = int(o['ts_ms']) // 1000
            else:
                ts = int(o['ts'])
            out.append((str(o['id']), o['emp'], dir_norm(o['dir']), ts))
    return out


def parse_offset(text, tz):
    out = []
    for row in csv.DictReader(io.StringIO('\n'.join(lines_of(text))), delimiter=';'):
        dt = datetime.fromisoformat(row['timestamp'].strip())
        out.append((row['punch_id'], row['employee'], dir_norm(row['event']), epoch_of(dt)))
    return out


def parse_legacy(text, tz):
    out = []
    off = None
    for l in lines_of(text):
        t = l[0]
        if t == 'H':
            rest = l[13:18].strip()
            if rest and rest[0] in '+-' and len(rest) == 5:
                s = 1 if rest[0] == '+' else -1
                off = timedelta(seconds=s * (int(rest[1:3]) * 3600 + int(rest[3:5]) * 60))
            else:
                off = None
        elif t == 'D':
            pid = l[1:9]
            badge = 'E' + l[9:15].strip()
            d = dir_norm(l[15])
            dt = datetime.strptime(l[16:30], '%Y%m%d%H%M%S')
            if off is not None:
                ep = int(dt.replace(tzinfo=UTC).timestamp()) - int(off.total_seconds())
            else:
                # standard offset of the zone at around that time
                guess = int(dt.replace(tzinfo=UTC).timestamp())
                so = std_offset(tz, guess)
                ep = guess - int(so.total_seconds())
                so2 = std_offset(tz, ep)
                ep = guess - int(so2.total_seconds())
            out.append((pid, badge, d, ep))
    return out


def parse_de(text, tz):
    out = []
    rows = [l.split('\t') for l in lines_of(text)]
    header = None
    for row in rows:
        row = [c.strip() for c in row]
        if 'Ausweis' in row:
            header = {n: i for i, n in enumerate(row)}
            continue
        if header is None:
            continue
        g = lambda n: row[header[n]]
        d, m, y = g('Datum').split('.')
        hh, mm = g('Uhrzeit').split(':')[:2]
        naive = datetime(int(y), int(m), int(d), int(hh), int(mm))
        z = g('Zeitzone').upper()
        dst = True if z == 'MESZ' else (False if z == 'MEZ' else None)
        out.append((g('Nr'), g('Ausweis'), dir_norm(g('Buchung')), local_to_epoch(naive, tz, dst)))
    return out


def parse_localcsv(text, tz):
    out = []
    for row in csv.DictReader(io.StringIO('\n'.join(lines_of(text)))):
        naive = datetime.strptime(row['local_time'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((row['punch_ref'].strip(), row['employee_id'].strip(), dir_norm(row['direction']),
                    local_to_epoch(naive, tz, None)))
    return out


def parse_localjsonl(text, tz):
    out = []
    for l in lines_of(text):
        o = json.loads(l)
        p = o.get('punch')
        if not isinstance(p, dict):
            continue
        naive = datetime.strptime(p['at'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((str(p['id']), p['badge'], dir_norm(p['type']), local_to_epoch(naive, tz, None)))
    return out


PARSERS = {'abbr-csv': parse_abbr, 'epoch-jsonl': parse_epoch, 'offset-csv': parse_offset,
           'legacy-fixed': parse_legacy, 'de-tsv': parse_de, 'local-csv': parse_localcsv,
           'local-jsonl': parse_localjsonl}


def read_csv(path):
    return list(csv.DictReader(io.StringIO('\n'.join(lines_of(read_text(path))))))


def parse_utc(s):
    s = s.strip()
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=UTC)
    return dt


def main(inp, outp):
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = parse_utc(period['corrections_cutoff'])
    sites = {r['site'].strip(): (ZoneInfo(r['timezone'].strip()), r['format'].strip())
             for r in read_csv(os.path.join(inp, 'sites.csv'))}
    emps = read_csv(os.path.join(inp, 'employees.csv'))
    home = {e['employee_id'].strip(): e['home_site'].strip() for e in emps}
    rates = {}
    for r in read_csv(os.path.join(inp, 'rates.csv')):
        rates.setdefault(r['employee_id'].strip(), []).append(
            (date.fromisoformat(r['effective_from'].strip()), Decimal(r['hourly_rate'].strip())))
    for v in rates.values():
        v.sort()

    punches = {}   # (site,id) -> [emp, dir, epoch]
    ever = set()
    for site in sorted(sites):
        tz, fmt = sites[site]
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        for root, _, files in os.walk(d):
            for fn in sorted(files):
                for pid, emp, dr, ep in PARSERS[fmt](read_text(os.path.join(root, fn)), tz):
                    k = (site, pid)
                    ever.add(k)
                    if k not in punches:
                        punches[k] = [emp.strip(), dr, ep]

    # corrections
    corr = []
    cdir = os.path.join(inp, 'corrections')
    if os.path.isdir(cdir):
        for root, _, files in os.walk(cdir):
            for fn in files:
                for r in read_csv(os.path.join(root, fn)):
                    corr.append(r)
    corr = [c for c in corr if parse_utc(c['issued_at']) <= cutoff]
    corr.sort(key=lambda c: (parse_utc(c['issued_at']), c['correction_id']))
    applied = 0
    for c in corr:
        k = (c['site'].strip(), c['punch_id'].strip())
        a = c['action'].strip().lower()
        if a == 'void':
            if k in punches:
                del punches[k]
                applied += 1
        elif a == 'set':
            if k in punches:
                punches[k][2] = epoch_of(datetime.fromisoformat(c['time'].strip()))
                applied += 1
        elif a == 'add':
            if k not in ever:
                ever.add(k)
                punches[k] = [c['employee'].strip(), dir_norm(c['type']),
                              epoch_of(datetime.fromisoformat(c['time'].strip()))]
                applied += 1
    per = {}
    for (site, pid), (emp, dr, ep) in punches.items():
        if emp in home:
            per.setdefault(emp, []).append((ep, 0 if dr == 'OUT' else 1, site, pid, dr))

    def rnd(ep, tz):
        off = int(datetime.fromtimestamp(ep, UTC).astimezone(tz).utcoffset().total_seconds())
        loc = ep + off
        return ((loc + 180) // 360) * 360 - off

    def workday(ep, htz):
        return datetime.fromtimestamp(ep, UTC).astimezone(htz).date()

    res = {}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)
    for e in home:
        res[e] = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Decimal(0))
    for emp, lst in per.items():
        htz = sites[home[emp]][0]
        lst.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
        kept = []
        for p in lst:
            ep, _, site, pid, dr = p
            r = rnd(ep, sites[site][0])
            if kept and kept[-1][4] == dr and ep - kept[-1][0] <= 300:
                if pstart <= workday(r, htz) <= pend:
                    exc['duplicates_dropped'] += 1
                continue
            kept.append(p)
        shifts = []
        cur = None

        def inper(r):
            return pstart <= workday(r, htz) <= pend
        for p in kept:
            ep, _, site, pid, dr = p
            r = rnd(ep, sites[site][0])
            if dr == 'IN':
                if cur:
                    if inper(cur[0]):
                        exc['open_shifts'] += 1
                cur = (r, site)
            else:
                if cur and r - cur[0] <= 16 * 3600:
                    shifts.append((cur[0], r, cur[1]))
                    cur = None
                else:
                    if cur:
                        if inper(cur[0]):
                            exc['open_shifts'] += 1
                        cur = None
                    if inper(r):
                        exc['orphan_outs'] += 1
        if cur and inper(cur[0]):
            exc['open_shifts'] += 1
        rows = []
        for a, b, site in shifts:
            wd = workday(a, htz)
            if not (pstart <= wd <= pend):
                continue
            worked = max(0, (b - a) // 60)
            paid = worked - 30 if worked > 360 else worked
            tz = sites[site][0]
            night = 0
            o1 = int(datetime.fromtimestamp(a, UTC).astimezone(tz).utcoffset().total_seconds())
            o2 = int(datetime.fromtimestamp(b, UTC).astimezone(tz).utcoffset().total_seconds())
            t = a
            while t < b:
                off = o1 if o1 == o2 else int(datetime.fromtimestamp(t, UTC).astimezone(tz).utcoffset().total_seconds())
                h = ((t + off) % 86400) // 3600
                if h >= 22 or h < 6:
                    night += 1
                t += 60
            night = min(night, paid)
            rows.append([a, wd, paid, night, 0])
        rows.sort(key=lambda x: x[0])
        daily = {}
        for r in rows:
            u = daily.get(r[1], 0)
            dot = max(0, u + r[2] - 480) - max(0, u - 480)
            daily[r[1]] = u + r[2]
            r.append(dot)  # r[5]
        week = {}
        for r in rows:
            wk = r[1] - timedelta(days=r[1].weekday())
            nd = r[2] - r[5]
            u = week.get(wk, 0)
            wot = max(0, u + nd - 2400) - max(0, u - 2400)
            week[wk] = u + nd
            r[4] = r[5] + wot
        rl = rates.get(emp, [])
        s = res[emp]
        total = Decimal(0)
        for a, wd, paid, night, ot, _ in rows:
            rate = None
            for ef, hr in rl:
                if ef <= wd:
                    rate = hr
            if rate is None and rl:
                rate = rl[0][1]
            rate = rate or Decimal(0)
            reg = paid - ot
            total += rate * (Decimal(reg) + Decimal('1.5') * ot) / 60 + rate * Decimal('0.15') * night / 60
            s['shifts'] += 1
            s['paid_minutes'] += paid
            s['overtime_minutes'] += ot
            s['night_minutes'] += night
        s['gross'] = total

    q = Decimal('0.01')
    out = {'period': {'start': period['start'], 'end': period['end']}, 'employees': {}, 'exceptions': exc}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    tg = Decimal(0)
    for e, s in res.items():
        g = s['gross'].quantize(q, rounding=ROUND_HALF_UP)
        tg += g
        out['employees'][e] = dict(s, gross=format(g, 'f'))
        for k in tot:
            tot[k] += s[k]
    out['totals'] = dict(tot, gross=format(tg, 'f'))
    with open(outp, 'w') as f:
        json.dump(out, f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
